 21	async function renderPlan(app, repo, slug) {
 22	  app.innerHTML = '<p class="loading">Loading plan\u2026</p>';
 23	  try {
 24	    var result = await API.getPlanDocument(repo, slug);
 25	    var html = marked.parse(result.content);
 26	    app.innerHTML =
 27	      breadcrumb().projects().project(repo, slug).leaf('Plan').html() +
 28	      '<div class="plan-content">' + html + '</div>';
 29	  } catch (err) {
 30	    if (err && err.code === 'NOT_FOUND') {
 31	      app.innerHTML =
 32	        breadcrumb().projects().project(repo, slug).leaf('Plan').html() +
 33	        '<p class="empty-state">Plan document not available for this project.</p>';
 34	    } else {
 35	      app.innerHTML = '<p class="error-banner">Failed to load plan document.</p>';
 36	    }
 37	  }
 38	}
