110	function renderProjectDetail(app, repo, slug) {
111	  // Drain log preview cleanup callbacks from the previous render.
112	  _pdLogPreviewCleanups.forEach(function (fn) { try { fn(); } catch (_) {} });
113	  _pdLogPreviewCleanups = [];
114	
115	  showLoading(app);
116	
117	  Promise.all([
118	    API.getProject(repo, slug),
119	    API.getPlanDocument(repo, slug).catch(function () { return null; }),
120	    API.getWorkPackageOverview(repo, slug).catch(function () { return null; }),
121	  ]).then(function (results) {
122	    var project = results[0];
123	    var planResult = results[1];
124	    var overviewResult = results[2]; // null if request failed (graceful degradation)
125	    var meta = project.meta || {};
126	    var wps = project.work_packages || [];
127	
128	    // Build a fast lookup: work_package_id → overview entry
129	    var overviewMap = {};
