131	      overviewResult.forEach(function (entry) {
132	        overviewMap[entry.work_package_id] = entry;
133	      });
134	    }
135	
136	    var useOverview = overviewResult !== null;
137	
138	    var wpRows = wps.map(function (wp) {
139	      var pipelineCell = useOverview
