165	                ctxItems +
166	              '</div>';
167	          }
168	          return '<div class="comment-card' + priorityClass + '">' +
169	            '<div class="comment-meta">' +
170	              escapeHtml(c.agent || '—') +
171	              ' <span class="comment-type">' + escapeHtml(c.type || '') + '</span>' +
172	              ' <span>' + escapeHtml(formatDate(c.timestamp)) + '</span>' +
173	            '</div>' +
174	            '<div style="margin-top:6px">' + escapeHtml(c.note || '') + '</div>' +
175	            contextHtml +
176	          '</div>';
177	        }).join('')
178	      : '<p class="text-muted">No comments yet.</p>';
179	
180	    var displayTitle = (project.project_name && project.project_name.trim()) ? project.project_name : ((meta.title && meta.title.trim()) ? meta.title : slug);
181	    ProjectNameCache.set(repo + '/' + slug, displayTitle);
182	    app.innerHTML =
183	      breadcrumb().projects().leafSpan(displayTitle, 'breadcrumb-title').html() +
184	      (meta.status === 'ARCHIVED' ?
185	        '<div class="info-banner" id="archive-banner">' +
186	          'This project is archived and hidden from the active list. ' +
187	          '<button class="btn btn-secondary btn-sm" id="unarchive-banner-btn">Unarchive</button>' +
188	        '</div>' : '') +
189	      '<div class="page-header">' +
190	        '<div class="page-heading-wrapper">' +
191	          '<h1 id="project-title-heading">' + escapeHtml(displayTitle) + '</h1>' +
192	          '<button class="edit-title-btn" id="edit-title-btn" title="Rename project">\u270e</button>' +
193	        '</div>' +
194	        statusBadge(meta.status) +
195	        '<span id="health-badge" class="health-badge">Checking\u2026</span>' +
196	        '<button class="btn btn-secondary btn-sm" id="reset-project-btn">Reset Project</button>' +
197	      '</div>' +
198	      '<div class="card">' +
199	        '<div class="text-muted" style="font-size:13px">' +
200	          '<strong>Slug:</strong> <span class="monospace" id="project-slug-value">' + escapeHtml(slug) + '</span>' +
201	          '<button class="edit-slug-btn" id="edit-slug-btn" title="Rename slug">✎</button><br>' +
202	          '<strong>Plan path:</strong> <span class="monospace">' + escapeHtml(meta.plan_path || '—') + '</span><br>' +
203	          '<strong>Created:</strong> ' + escapeHtml(formatDate(meta.date_created)) + ' &nbsp; ' +
204	          '<strong>Updated:</strong> ' + escapeHtml(formatDate(meta.last_updated)) +
205	          (project.timing
206	            ? '<br><strong>Duration:</strong> ' + escapeHtml(formatDuration(project.timing.project_elapsed_ms)) +
207	                (project.timing.pipeline_runs > 0
208	                  ? ' &nbsp;\u00b7&nbsp; <strong>Active:</strong> ' + escapeHtml(formatDuration(project.timing.total_active_ms)) + ' across ' + project.timing.pipeline_runs + ' pipeline runs'
