211	          (project.server_version ? '<br><strong>Server version:</strong> <span class="monospace">v' + escapeHtml(project.server_version) + '</span>' : '') +
212	          (project.ledger_version ? ' &nbsp; <strong>Spec version:</strong> <span class="monospace">v' + escapeHtml(project.ledger_version) + '</span>' : '') +
213	        '</div>' +
214	      '</div>' +
215	
216	      (function () {
217	        var synopsisHtml = '';
218	        if (planResult && planResult.content) {
219	          var synopsis = extractSynopsis(planResult.content);
220	          if (synopsis) {
221	            synopsisHtml =
222	              '<div class="plan-synopsis">' +
223	              '<div class="plan-synopsis__content">' + marked.parse(synopsis) + '</div>' +
224	              '<a href="#/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/plan" class="plan-synopsis__link">View full plan \u2192</a>' +
225	              '</div>';
226	          }
