229	      })() +
230	
231	      (function () {
232	        if (!project.synthesis_generated) return '';
233	        return '<div class="synthesis-link-row">' +
234	          '<a href="#/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/synthesis" class="synthesis-link">View synthesis \u2192</a>' +
