237	
238	      '<div class="card-title">Work Packages</div>' +
239	      (wps.length
240	        ? '<div class="table-wrapper"><table>' +
241	            '<thead><tr><th>WP ID</th><th>' + (useOverview ? 'Pipeline Stages' : 'WP ID') + '</th><th>Assigned To</th><th>Status</th></tr></thead>' +
242	            '<tbody>' + wpRows + '</tbody>' +
243	          '</table></div>'
244	        : '<p class="text-muted">No work packages.</p>') +
245	      '<div class="card-title" style="margin-top:24px">Project Comments</div>' +
246	      commentCards +
