248	      // Orchestrator Runs section — rendered for any project; shown only when logs exist
249	      '<div id="orchestrator-runs-wrapper" style="display:none">' +
250	        '<div class="card-title" style="margin-top:24px">Orchestrator Runs</div>' +

251	    }
