254	  // ------------------------------------------------------------------
255	  // renderLogPreview(container, repo, slug, filename) → cleanup()
256	  // ------------------------------------------------------------------
257	
258	  /**
259	   * Starts auto-polling the run log for a queue entry and prepends new
260	   * JSONL events to `container` as they arrive, keeping the most-recent
261	   * entry at the top (most-recent-first ordering).
262	   *
263	   * Polling begins immediately (one fetch on call), then repeats every
264	   * 3 seconds.  Only events after the last seen line are prepended.
265	   *
266	   * @param {HTMLElement} container - The element to prepend log entries into.
267	   * @param {string}      repo      - Repository name that owns the project (URI-encoded by API client).
268	   * @param {string}      slug      - Project slug used for the API call (URI-encoded by API client).
269	   * @param {string}      filename  - JSONL log filename.
270	   * @returns {Function} cleanup — call to stop polling and clear the interval.
271	   */
272	  function renderLogPreview(container, repo, slug, filename) {
273	    var afterLine  = 0;
274	    var stopped    = false;
275	    var intervalId = null;
276	
277	    function fetchEntries() {
278	      if (stopped) return;
279	      API.getRunLogEntries(repo, slug, filename, afterLine).then(function (data) {
280	        if (stopped) return;
281	        var entries    = (data && Array.isArray(data.entries)) ? data.entries : [];
282	        var totalLines = (data && typeof data.totalLines === 'number')
283	          ? data.totalLines
284	          : afterLine;
285	
286	        // Iterate in reverse so that within a batch the earliest entry
287	        // ends up at the top after prepending (each insertBefore pushes
288	        // the previous div down, so the last-iterated entry — the oldest
289	        // in the batch — ends up topmost).  Overall result: newest events
290	        // are always visible at the top without scrolling.
291	        for (var i = entries.length - 1; i >= 0; i--) {
